import{_ as r,o,c as a,a as e}from"./chunks/framework.Ld7uezS_.js";const b=JSON.parse('{"title":"考核说明","description":"","frontmatter":{},"headers":[],"relativePath":"exam-guide.md","filePath":"exam-guide.md","lastUpdated":1787292351000}'),l={name:"exam-guide.md"};function n(s,t,i,d,h,g){return o(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="考核说明" tabindex="-1">考核说明 <a class="header-anchor" href="#考核说明" aria-label="Permalink to &quot;考核说明&quot;">​</a></h1><p>本页帮你搞清楚：消防设施操作员（四级 / 中级工）<strong>考什么、怎么报名、题型与合格线、该怎么准备</strong>。</p><blockquote><p><strong>版本与证据边界（截至 2026-08-21；报考前请重新核验）</strong>：2026 年版《消防设施操作员国家职业标准》公开信息显示自 2026-10-01 起施行；在施行日前，本站仍按 2019 年版组织当前学习基线。施行后必须重新核对职业方向、申报条件、技能要求和考核口径。</p><p>职业等级、职业方向、职业功能和“理论知识考试＋技能考核、两科均须合格”等内容以《消防设施操作员国家职业技能标准（2019 年版）》为基线；技能考核方式和考务细节还受消防行业职业技能鉴定指导中心及当地鉴定站最新公告影响。自 2024-11-19 起，官方已公告的新报名考生技能考核实行现场实际操作，不能再把旧的线上仿真安排当作全国当前统一规则。见<a href="https://xfhyjd.119.gov.cn/zwossread/open1File/FirefightingSkillsAssessmentSystem/2025-11-13/4f0f6d863cf843228b5ce52030b59bb7/16193156145476990d82b-cb9d-43a7-a5f0-522abe3d1f8c%E5%9B%BD%E5%AE%B6%E8%81%8C%E4%B8%9A%E6%8A%80%E8%83%BD%E6%A0%87%E5%87%86%E2%80%94%E2%80%94%E6%B6%88%E9%98%B2%E8%AE%BE%E6%96%BD%E6%93%8D%E4%BD%9C%E5%91%98.pdf" target="_blank" rel="noreferrer">国家职业技能标准原文</a>、<a href="https://xfhyjd.119.gov.cn/" target="_blank" rel="noreferrer">消防职业技能鉴定考试网</a>和<a href="https://xfhyjd.119.gov.cn/#/detail/tzgg/2887" target="_blank" rel="noreferrer">四川鉴定站 2025 年备考提示（示例）</a>。具体以报考地最新公告和准考证为准。</p></blockquote><h2 id="一、职业与等级" tabindex="-1">一、职业与等级 <a class="header-anchor" href="#一、职业与等级" aria-label="Permalink to &quot;一、职业与等级&quot;">​</a></h2><p><strong>消防设施操作员</strong>是从事建（构）筑物消防设施运行、操作和维修、保养、检测等工作的人员。国家职业资格共五个等级：</p><table tabindex="0"><thead><tr><th>等级</th><th>名称</th></tr></thead><tbody><tr><td>五级 / 初级工</td><td>初级消防设施操作员</td></tr><tr><td><strong>四级 / 中级工</strong></td><td><strong>中级消防设施操作员（本站点目标）</strong></td></tr><tr><td>三级 / 高级工</td><td>高级消防设施操作员</td></tr><tr><td>二级 / 技师</td><td>消防技师</td></tr><tr><td>一级 / 高级技师</td><td>消防高级技师</td></tr></tbody></table><h2 id="二、报考条件-中级工-四级" tabindex="-1">二、报考条件（中级工 / 四级） <a class="header-anchor" href="#二、报考条件-中级工-四级" aria-label="Permalink to &quot;二、报考条件（中级工 / 四级）&quot;">​</a></h2><p>下列条件来自《消防设施操作员国家职业技能标准（2019年版）》中级申报条件的学习基线，<strong>不是对当前批次资格审核结果的承诺</strong>。实际报名还要以报考地鉴定站当批次公告、报名系统材料清单和资格审核意见为准：</p><ol><li>取得本职业初级（五级）证书后，累计从事本职业工作 <strong>4 年（含）以上</strong>；</li><li>累计从事本职业工作 <strong>6 年（含）以上</strong>；</li><li>取得技工学校本专业或相关专业毕业证书（含应届在校毕业生）；</li><li>取得经评估论证、以中级技能为培养目标的中等及以上职业学校本专业或相关专业毕业证书（含应届在校毕业生）。</li></ol><blockquote><p>报名材料中的职业、专业、工作年限、证书和应届身份应能提供真实、清晰、完整的证明。不同批次对材料格式、补充材料和审核时间可能有具体要求，不要仅凭培训机构口头说明判断是否符合条件。</p></blockquote><h2 id="三、考试科目" tabindex="-1">三、考试科目 <a class="header-anchor" href="#三、考试科目" aria-label="Permalink to &quot;三、考试科目&quot;">​</a></h2><p>中级工考核分 <strong>两科，均须合格</strong>：</p><table tabindex="0"><thead><tr><th>科目</th><th>形式</th><th>说明</th></tr></thead><tbody><tr><td>理论知识考试</td><td>机考 / 闭卷</td><td>单选、多选、判断题</td></tr><tr><td>技能操作考核</td><td>现场实际操作（当前新报名考生的官方主规则）</td><td>按职业方向和鉴定细则实操；关键技能（★）未达到要求可能直接判定技能不合格</td></tr></tbody></table><h2 id="四、理论考试-题型与合格线" tabindex="-1">四、理论考试（题型与合格线） <a class="header-anchor" href="#四、理论考试-题型与合格线" aria-label="Permalink to &quot;四、理论考试（题型与合格线）&quot;">​</a></h2><ul><li><strong>题型</strong>：以当地鉴定站当批次公告和考试系统显示为准；常见题型包括单项选择题、多项选择题、判断题。</li><li><strong>题量 / 时长</strong>：本站不再把“200 题、100 分钟”等旧资料中的具体参数写成全国统一规则。当前公开公告通常只明确机考形式和考试安排，题量、分值、时长可能由鉴定实施细则或系统配置确定；请以报考地最新公告、准考证和考场系统为准。</li><li><strong>合格线</strong>：国家职业技能标准规定理论知识考试、技能考核均实行百分制，成绩 <strong>60 分（含）以上</strong>为合格；具体评分细则仍以鉴定机构当批次规则为准。</li><li><strong>内容范围</strong>：职业道德、消防工作概述、燃烧和火灾基础知识、建筑防火基础知识、电气消防基础知识、消防设施基础知识、初起火灾处置知识、计算机基础知识、相关法律法规知识、安全生产与职业健康，共 10 个基础模块。</li></ul><h2 id="五、技能操作考核-职业功能与方向" tabindex="-1">五、技能操作考核（职业功能与方向） <a class="header-anchor" href="#五、技能操作考核-职业功能与方向" aria-label="Permalink to &quot;五、技能操作考核（职业功能与方向）&quot;">​</a></h2><p>中级工设 <strong>两个职业方向</strong>，报名时即须确定，技能考核范围不同：</p><ul><li><strong>消防设施监控操作方向</strong>：考核 <strong>设施监控、设施操作、设施保养</strong> 3 项职业功能；</li><li><strong>消防设施检测维修保养方向</strong>：考核 <strong>设施操作、设施保养、设施维修、设施检测</strong> 4 项职业功能。</li></ul><blockquote><p>两个方向的理论基础模块一致，技能考核范围不同，请按自身岗位 / 就业方向选择。</p></blockquote><p>考核形式：当前新报名考生以现场实际操作为主，满分 100 分，<strong>60 分及以上</strong>为标准基线；具体项目、分值和评分表以报考地鉴定站当批次公告为准。</p><ul><li><strong>关键技能（★）</strong>：标准中标注「★」的项目涉及安全生产或核心操作。违反操作规程、未达到项目要求或未达到当地评分表规定的关键技能分值门槛，可能直接判定技能考核不合格；本站不把“一票否决”扩展解释为所有地区完全相同的评分细则。</li><li>训练重点包括：火灾报警控制器和联动控制器操作、消防泵组、防排烟、防火卷帘、应急广播、消防电话、应急照明与疏散指示等系统的状态识别、操作、反馈确认和恢复。</li></ul><h2 id="六、考试流程-一般情况" tabindex="-1">六、考试流程（一般情况） <a class="header-anchor" href="#六、考试流程-一般情况" aria-label="Permalink to &quot;六、考试流程（一般情况）&quot;">​</a></h2><ol><li><strong>报名</strong>：通过当地消防行业职业技能鉴定站 / 官方报名渠道报名，提交学历、工作年限等证明。</li><li><strong>审核</strong>：鉴定站审核报考资格。</li><li><strong>参加考试</strong>：先考理论，再考技能（顺序以当地安排为准）。</li><li><strong>成绩查询</strong>：考后按规定时间查询。</li><li><strong>发证或取得评价结果</strong>：两科均合格后，按鉴定机构流程取得相应等级评价证书或证书信息；证书查询、发放形式和时间以官方流程为准。</li></ol><blockquote><p>关于单科成绩保留期限、补考次数和补考流程，不同批次或地区可能存在具体安排；报名和参加考试前，必须以报考地鉴定站当批次公告、准考证或官方通知为准，本站不将旧资料中的“一年、一次”等说法作为全国统一规则。</p></blockquote><h2 id="七、证书与补贴" tabindex="-1">七、证书与补贴 <a class="header-anchor" href="#七、证书与补贴" aria-label="Permalink to &quot;七、证书与补贴&quot;">​</a></h2><ul><li>证书全国通用，可在「技能人才评价证书全国联网查询系统」核验。</li><li>符合条件者可申领 <strong>技能提升补贴</strong>（以当地人社部门政策为准）。</li></ul><h2 id="八、怎么用本站点备考" tabindex="-1">八、怎么用本站点备考 <a class="header-anchor" href="#八、怎么用本站点备考" aria-label="Permalink to &quot;八、怎么用本站点备考&quot;">​</a></h2><ol><li>先读本页，明确目标与科目。</li><li>按侧边栏顺序学完 <strong>理论考试 10 个模块</strong>，建立知识体系。</li><li>进入 <strong>检测维修保养方向四项核心职业功能</strong>，并把设施监控作为理解控制器状态和反馈信息的基础，结合实操理解设备与流程。</li><li>用右上角「搜索」随时查漏补缺。</li></ol><p>下一步：<a href="/theory/01-professional-ethics">理论考试 · 第 1 章 职业道德 →</a></p>',29)])])}const u=r(l,[["render",n]]);export{b as __pageData,u as default};
